<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Patient dashboard · MOA</title><link rel="stylesheet" href="/app.css"></head><body><main class="dashboard-page"><header class="dashboard-header"><a class="brand" href="/"><span class="brand-mark"><i></i><i></i></span>MOA</a><form method="POST" action="{{ route('auth.logout') }}">@csrf<button class="text-button">Log out</button></form></header><section class="dashboard-intro"><div class="eyebrow">PATIENT PORTAL</div><h1>Good to see you, <em>{{ $user->name }}</em></h1><p>Manage your care, appointments, and prescription history in one secure place.</p>@if(session('success'))<p class="success-message">{{ session('success') }}</p>@endif</section><div class="dashboard-grid"><section class="dashboard-card"><h2>Profile</h2><p class="status-badge">{{ $user->hasVerifiedEmail() ? 'Email verified' : 'Email verification pending' }}</p><form method="POST" action="{{ route('profile.update') }}">@csrf @method('PATCH')<input name="name" value="{{ old('name', $user->name) }}" required><input name="email" type="email" value="{{ old('email', $user->email) }}" required><input name="phone" value="{{ old('phone', $user->phone) }}" placeholder="Phone"><button class="button button-teal">Save profile</button></form></section><section class="dashboard-card"><h2>Upcoming appointments</h2>@forelse($upcomingAppointments as $appointment)<div class="record-row"><div><strong>{{ $appointment->service }}</strong><small>{{ $appointment->starts_at->format('M j, Y · g:i A') }}</small></div>@if($appointment->status !== 'cancelled')<form method="POST" action="{{ route('appointments.cancel', $appointment) }}">@csrf @method('DELETE')<button class="text-button">Cancel</button></form>@endif</div>@empty<p class="empty-state">No upcoming appointments.</p>@endforelse</section><section class="dashboard-card"><h2>Prescription history</h2>@forelse($prescriptions as $prescription)<div 